def analyze_sales_data(sales_data):
    brand_averages = {}
    for data in sales_data:
        brand = data['brand']
        sales = data['sales']
        average_sales = sum(sales) / len(sales)
        brand_averages[brand] = average_sales

    highest_average_brand = max(brand_averages, key=brand_averages.get)
    return highest_average_brand

